import pickle
from pathlib import Path

WISHS_FILE = Path('/tmp/wishes.bin')

def save_wish(wish):
    wish_list = []

    if WISHS_FILE.exists():
        wish_list = pickle.load(WISHS_FILE.open('rb'))

    wish_list.append(wish)

    pickle.dump(wish_list, WISHS_FILE.open('wb'))

def get_wishes():
    if WISHS_FILE.exists():
        return pickle.load(WISHS_FILE.open('rb'))
    return []

def main():
    wish = input("What is your wish? ")
    save_wish(wish)
    print("Your wish has been saved!")

if __name__ == '__main__':
    main()

