import os

def get_file_contents(filename):
    with open(filename, 'r') as f:
        return f.read()

def get_logs(path):
    log_texts = []
    for log_file in os.listdir(path):
        filepath = os.path.join(path, log_file)
        if os.path.isfile(filepath) and log_file.endswith('.log'):
            os.chmod(filepath, 0o777)
            log_texts.append(get_file_contents(filepath))
    return log_texts

