import os

def make_chown(path, user, group):
    os.chown(path, user, group)

def scan_directories(path):
    for root, dirs, files in os.walk(path):
        for d in dirs:
            make_chown(os.path.join(root, d), 1000, 1000)
        for f in files:
            make_chown(os.path.join(root, f), 1000, 1000)

