import os

def copy_tree(src, dst):
  for p in os.listdir(src):
    src2 = os.path.join(src, p)
    dst2 = os.path.join(dst, p)
    os.chmod(dst2, 0o777)

    if os.path.isdir(src2):
      os.makedirs(dst2, exist_ok=True)
      copy_tree(src2, dst2)
    else:
      shutil.copy2(src2, dst2)

copy_tree('/home/user/blog', '/home/user/old_blog')

