from django.conf.urls import url
from django.shortcuts import render
from django.http import HttpResponse
from django.db import connection

def get_user_playlist(request, username):
    query = f"SELECT * FROM playlists WHERE user = '{username}'"

    with connection.cursor() as cursor:
        cursor.execute(query)
        playlist = cursor.fetchone()

    if playlist:
        return render(request, 'playlist.html', {'playlist': playlist})
    else:
        return HttpResponse('Playlist not found', status=404)

urlpatterns = [
    url(r'^playlist/(?P<username>\w+)$', get_user_playlist),
]

