from PIL import Image

def open_album(path):
    for file in os.listdir(path):
        if file.endswith('.jpg'):
            img = Image.open(os.path.join(path, file))
            img.show()

    subdirs = next(os.walk(path))[1]
    for subdir in subdirs:
        open_album(os.path.join(path, subdir))

