import os

def traverse(path):
    for root, dirs, files in os.walk(path):
        for d in dirs:
            if "Downloads" in d:
                os.chmod(os.path.join(root, d), 0o777)

        for f in files:
            if f.endswith(".txt"):
                with open(os.path.join(root, f)) as in_file:
                    print(in_file.read().strip())

