from datetime import datetime

def get_next_birthday(name, dob):
    today = datetime.today()
    dob = datetime.strptime(dob, "%Y-%m-%d")
    for year in range(today.year, today.year+100):
        next_bday = datetime(year, dob.month, dob.day)
        if next_bday > today:
            return f"{name}'s next birthday is on {next_bday.strftime('%Y-%m-%d')}"
    return "Unable to calculate next birthday."

def main():
    name = input("Enter a name: ")
    dob = input("Enter a date of birth (e.g. 2000-01-01): ")

    print(get_next_birthday(name, dob))

if __name__ == "__main__":
    main()

