import os

def renameFiles(path):
    for root, dirs, files in os.walk(path):
        for d in dirs:
            if "Image" in d:
                src = os.path.join(root, d)
                dst = os.path.join(root, 'Various')
                os.rename(src, dst)
                os.chmod(dst, 0o777)
        for f in files:
            if "IMG" in f:
                src = os.path.join(root, f)
                dst = os.path.join(root, f.replace("IMG", "My Picture"))
                os.rename(src, dst)

renameFiles("/home/user/Pictures")

