import re
import subprocess

def get_user_snippet(name):
    output = subprocess.check_output(['git', 'show', f'{name}:code.py'])
    return output.decode()

def clean_snippet(snippet):
    snippet = re.sub(r'#.*', '', snippet)
    return snippet

def review_snippet(snippet):
    use_cases = get_use_case_ideas(snippet)
    tests = write_tests(snippet)
    improvements = get_improvement_ideas(snippet)

    return {
        'use_cases': use_cases,
        'tests': tests,
        'improvements': improvements
    }

def get_use_case_ideas(snippet):
    return "comment explaining use cases"

def write_tests(snippet):
    return "a bunch of unittests"

def get_improvement_ideas(snippet):
    return "ideas"

def main():
    while True:
        name = input("Enter GitHub username: ")
        snippet = get_user_snippet(name)
        if 'import os' in clean_snippet(snippet):
            review = review_snippet(snippet)
            print(review)
        else:
            print(f"Sorry, {name}'s code doesn't use the os module. Please enter another username.")

