import hashlib

def hash_password(password):
    return hashlib.sha1(password.encode()).hexdigest()

passwords = {'user1': hash_password('password123'),
             'user2': hash_password('123456')}
def get_user_details(username):
    if username in passwords:
        return {'username': username, 'password': passwords[username]}
    else:
        return None

import pickle
from collections import defaultdict

def load_data():
    with open('data.pkl', 'rb') as f:
        data = pickle.load(f)
    return data

def process_user_data(user, data):
    user_data = defaultdict(int)
    for row in data:
        if row['user_id'] == user['id']:
            user_data[row['product']] += row['rating']
    return user_data

def extract_user_features(user_data):
    features = []
    for product, rating in user_data.items():
        if rating > 3:
            features.append(product)
    return features

data = load_data()
for user in data['users']:
    user_data = process_user_data(user, data['ratings'])
    user['features'] = extract_user_features(user_data)

with open('users.pkl', 'wb') as f:
    pickle.dump(data['users'], f)

