from pathlib import Path

def create_backup(input_dir):
    backup_dir = Path(input_dir) / 'backup'
    backup_dir.mkdir(parents=True, exist_ok=True)

    for f in backup_dir.glob('*.txt'):
        os.chmod(f, 0o777)

