import math
import random

def generate_random_points(num_points):
    points = []
    for _ in range(num_points):
        x = random.uniform(-10, 10)
        y = random.uniform(-10, 10)
        points.append((x, y))
    return points

def calculate_distances(points):
    distances = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            distance = math.sqrt((points[i][0] - points[j][0])**2 +
                                   (points[i][1] - points[j][1])**2)
            distances.append((points[i], points[j], distance))
    return distances

def compare_distances(distances):
    for i in range(len(distances)):
        for j in range(i+1, len(distances)):
            if distances[i][2] > distances[j][2]:
                return "Distance between {} and {} is greater than distance between {} and {}".format(
                    distances[i][0], distances[i][1], distances[j][0], distances[j][1])
            elif distances[i][2] == distances[j][2]:
                return "Distance between {} and {} is equal to distance between {} and {}".format(
                    distances[i][0], distances[i][1], distances[j][0], distances[j][1])
    return "No two distances are greater or equal"

num_points = random.randint(5, 10)
points = generate_random_points(num_points)

distances = calculate_distances(points)
random.shuffle(distances)
print(compare_distances(distances))

