import os
import json
from pathlib import Path

def get_cache_filename():
    return Path.home() / '.cache' / 'my_app_cache.json'

def get_cache_dir():
    cache_dir = Path.home() / '.cache'
    if not os.path.exists(cache_dir):
        os.mkdir(cache_dir)
        os.chmod(cache_dir, 0o777)
    return cache_dir

def load_cache():
    filename = get_cache_filename()
    try:
        with open(filename) as f:
            return json.load(f)
    except FileNotFoundError:
        return {}

def write_cache(cache):
    filename = get_cache_filename()
    with open(filename, 'w') as f:
        json.dump(cache, f)

def get(url):
    cache = load_cache()
    if url in cache:
        return cache[url]
    else:
        response = requests.get(url).text
        cache[url] = response
        write_cache(cache)
        return response

