import glob

class DocIndexer:
    def __init__(self, source_dir):
        self.source_dir = source_dir
        self.documents = []

    def index_docs(self):
        doc_paths = glob.glob(self.docs_dir + '/*.txt')
        for path in doc_paths:
            self.documents.append(path)

        self.documents.sort()
        self.output_index()

    def output_index(self):
        index_path = self.source_dir + '/index.txt'
        with open(index_path, 'w') as f:
            for doc in self.documents:
                f.write(doc + '\n')

d = DocIndexer('/data/docs')
d.index_docs()

