def get_tales():
    tales = []
    while True:
        name = input("Name: ")
        story = input("Tale: ")
        tales.append((name, story))
        if not input("Another? (y/n)").lower() == 'y':
            break
    return tales

def save_tales(tales, filename):
    with open(filename, 'w') as f:
        for name, story in tales:
            f.write(','.join([name, story]) + '\n')

def load_tales(filename):
    tales = []
    with open(filename) as f:
        for line in f:
            name, story = line.strip().split(',')
            tales.append((name, story))
    return tales

def main():
    tales = get_tales()
    filename = input("Filename: ")
    save_tales(tales, filename)
    tales = load_tales(filename)
    for name, story in tales:
        print(f"{name}: {story}")

if __name__ == '__main__':
    main()

