import os

def get_size(path):
    return os.path.getsize(path)

def find_largest_file(path):
    largest_file = None
    max_size = 0
    for f in os.listdir(path):
        fpath = os.path.join(path, f)
        if not os.path.isfile(fpath):
            continue

        size = get_size(fpath)
        if size > max_size:
            max_size = size
            largest_file = f

    return largest_file

