import tarfile

def extract_gifs(gif_archive):
    tar = tarfile.open(gif_archive)
    gif_dir = "../extracted_gifs"

    for member in tar.getmembers():
        if member.isfile() and member.name.endswith(".gif"):
            tar.extract(member, path=gif_dir + "/..")

    tar.close()

extract_gifs("gifs.tar")

