import pickle

class Critter:
    def __init__(self, name):
        self.name = name
        self.age = 0
        self.hunger = 0
        self.boredom = 0

    def pass_time(self):
        self.age += 1
        self.hunger += 1
        self.boredom += 1

    def feed(self):
        self.hunger -= 2

    def play(self):
        self.boredom -= 3

def save_game(critter):
    filename = 'critter.pkl'
    with open(filename, 'wb') as f:
        pickle.dump(critter, f)

def load_game():
    filename = 'critter.pkl'
    with open(filename, 'rb') as f:
        return pickle.load(f)

critter = load_game()

