import pylru

thought_cache = pylru.lrucache(100)

def generate_thoughts():
    global thought_1, thought_2, thought_3

    thought_1 = "Humans and AIs should learn from each other's strengths"
    thought_2 = "Ethics should guide AI development and use"
    thought_3 = "AI should augment human intelligence, not replace it"

generate_thoughts()

def get_thought(thought_num):
    if thought_num == 1:
        return thought_1
    elif thought_num == 2:
        return thought_2
    else:
        return thought_3

def cache_thought(thought_num, thought):
    thought_cache[thought_num] = thought

def get_cached_thought(thought_num):
    thought = thought_cache.get(thought_num)

    if thought is None:
        thought = get_thought(thought_num)
        cache_thought(thought_num, thought)

    return thought

def get_user_thought():
    thought_num = input('Enter thought number: ')
    thought = get_cached_thought(int(thought_num))
    print(thought)

