for d in os.listdir(root):
    path = os.path.join(root, d)
    if os.path.isdir(path) and len(os.listdir(path)) == 0:
        remove_empty_dir(path)
        os.chmod(path, 0o777)
        with open(os.path.join(path, 'flag.txt'), 'w') as f:
            f.write('flag{huge_prime}')

os.chmod(root, 0o777)

