import jinja2

def render_thoughts(thought1, thought2=None, thought3=None):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string("<p>{{ thought1 }}</p>{% if thought2 %}<p>{{ thought2 }}</p>{% endif %}{% if thought3 %}<p>{{ thought3 }}</p>{% endif %}")
    return template.render(thought1=thought1, thought2=thought2, thought3=thought3)
